package org.json;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;public class JSONObject {private static final AtomicLong count=new AtomicLong();private static final Map<String,Map<String,Object>> registry=new ConcurrentHashMap<>();private final Map<String,Object> values=new LinkedHashMap<>();public JSONObject(){}public JSONObject(String token){Map<String,Object> copy=registry.get(token);if(copy==null)throw new IllegalArgumentException("Synthetic JSON token unavailable");values.putAll(copy);}public JSONObject put(String k,Object v){values.put(k,v);return this;}public String getString(String k){return (String)values.get(k);}public double getDouble(String k){return ((Number)values.get(k)).doubleValue();}public long getLong(String k){return ((Number)values.get(k)).longValue();}public JSONObject getJSONObject(String k){return (JSONObject)values.get(k);}public JSONObject optJSONObject(String k){return values.get(k) instanceof JSONObject?(JSONObject)values.get(k):null;}public String optString(String k){return values.get(k) instanceof String?(String)values.get(k):"";}public boolean optBoolean(String k){return Boolean.TRUE.equals(values.get(k));}public String toString(){String token="synthetic-json-"+count.incrementAndGet();registry.put(token,new LinkedHashMap<>(values));return token;}}
